/** Tiny placeholder — shows instantly while the real image loads. */
export const IMAGE_BLUR_DATA_URL =
  "data:image/jpeg;base64,";

export function isOptimizableImageSrc(src: string | { src: string }): boolean {
  const value = typeof src === "string" ? src : src.src;
  if (!value || value.startsWith("data:") || value.startsWith("blob:")) return false;
  return true;
}
